-- Row-Level Security policies for the shared-schema multi-tenancy model
-- (blueprint §4). Apply this AFTER running Drizzle migrations that create
-- the tables below, e.g.:
--
--   psql "$DATABASE_URL" -f drizzle/rls-policies.sql
--
-- This file is hand-written raw SQL, not generated by drizzle-kit: RLS
-- policies aren't part of this scaffold's Drizzle migration pipeline.
--
-- ---------------------------------------------------------------------------
-- Runtime role note (blueprint §4 point 4):
-- ---------------------------------------------------------------------------
-- The application's runtime DB connection (what `apps/backend`'s
-- `postgres`/Drizzle client authenticates as) MUST use a role created
-- with NOBYPASSRLS, e.g.:
--
--   CREATE ROLE faktur_app WITH LOGIN PASSWORD '...' NOBYPASSRLS;
--   GRANT CONNECT ON DATABASE faktur TO faktur_app;
--   GRANT USAGE ON SCHEMA public TO faktur_app;
--   GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO faktur_app;
--
-- NOBYPASSRLS is actually Postgres's default for new roles (BYPASSRLS is
-- opt-in), but it's called out explicitly here because table owners and
-- superusers DO bypass RLS by default regardless of the BYPASSRLS role
-- attribute — so the app must NOT connect as the table owner or a
-- superuser, or every policy below becomes a no-op. Run Drizzle migrations
-- as a separate, more privileged "migration" role (which owns the tables);
-- have the app connect as `faktur_app`, a non-owner role that only has the
-- DML grants above.
--
-- This script itself must be run as a role with sufficient privilege to
-- ALTER TABLE / CREATE POLICY (the table-owning migration role, or a
-- superuser) — not as `faktur_app`.

-- ---------------------------------------------------------------------------
-- tenants
-- ---------------------------------------------------------------------------
-- `tenants` doesn't carry a `tenant_id` column (it IS the tenant), so its
-- policy compares `id` directly instead of `tenant_id`.
--
-- Bootstrap caveat: signup/tenant-creation happens before
-- `app.current_tenant_id` can possibly be set (the tenant doesn't exist
-- yet). That INSERT path must run through a mechanism this policy doesn't
-- cover on its own — e.g. a `SECURITY DEFINER` function, or a narrow
-- separate INSERT policy `WITH CHECK (true)` restricted to a dedicated
-- "signup" role. Not wired up in this scaffold; see the TODO in
-- `src/tenants/tenants.controller.ts`.
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS tenant_isolation ON tenants;
CREATE POLICY tenant_isolation ON tenants
  USING (id = current_setting('app.current_tenant_id', true)::uuid);

